def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    undo_stack: list[tuple] = []
    rejected: list[int] = []

    def amount(token: str) -> int | None:
        if token == "" or any(c < "0" or c > "9" for c in token):
            return None
        return int(token)

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False
        if verb == "open" and len(parts) == 3:
            name, n = parts[1], amount(parts[2])
            if n is not None and name not in balances:
                balances[name] = n
                undo_stack.append(("open", name))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            name, n = parts[1], amount(parts[2])
            if n is not None and n > 0 and name in balances:
                balances[name] += n
                undo_stack.append(("deposit", name, n))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            name, n = parts[1], amount(parts[2])
            if (
                n is not None
                and n > 0
                and name in balances
                and name not in frozen
                and balances[name] >= n
            ):
                balances[name] -= n
                undo_stack.append(("withdraw", name, n))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            src, dst, n = parts[1], parts[2], amount(parts[3])
            if (
                n is not None
                and n > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= n
            ):
                balances[src] -= n
                balances[dst] += n
                undo_stack.append(("transfer", src, dst, n))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            name = parts[1]
            if name in balances and name not in frozen:
                frozen.add(name)
                undo_stack.append(("freeze", name))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            name = parts[1]
            if name in balances and name in frozen:
                frozen.remove(name)
                undo_stack.append(("unfreeze", name))
                ok = True
        elif verb == "undo" and len(parts) == 1 and undo_stack:
            rec = undo_stack.pop()
            kind = rec[0]
            if kind == "open":
                frozen.discard(rec[1])
                del balances[rec[1]]
            elif kind == "deposit":
                balances[rec[1]] -= rec[2]
            elif kind == "withdraw":
                balances[rec[1]] += rec[2]
            elif kind == "transfer":
                balances[rec[1]] += rec[3]
                balances[rec[2]] -= rec[3]
            elif kind == "freeze":
                frozen.discard(rec[1])
            else:
                frozen.add(rec[1])
            ok = True
        if not ok:
            rejected.append(i)
    return balances, rejected
